+        .map(|t| t["inputSchema"]["properties"]["params"]["description"].as_str().unwrap_or_default().to_owned())
+        .unwrap_or_default();
+    assert!(doc.contains("Deburr") && doc.contains("edge chain"), "the schema names the chain kind: {doc}");
+}

